// BuildIcebergSchemaMigrationSQL validates evolving a slice of before table descriptors
// into after table descriptors and returns the ordered Apache Iceberg DDL statements:
// ALTER TABLE statements for evolved existing tables and CREATE TABLE IF NOT EXISTS
// statements for newly added tables. Rejects dropping existing Iceberg tables.
func BuildIcebergSchemaMigrationSQL(before, after []DorisTableDescriptor, tenantSlug string) ([]string, error) {
	if _, ok := sanitizeDorisTenantSlug(tenantSlug); !ok {
		return nil, fmt.Errorf("invalid tenantSlug %q in BuildIcebergSchemaMigrationSQL", tenantSlug)
	}
	beforeByKey, _, _, _, err := indexDorisSchemaEvolutionTables(before, after, "BuildIcebergSchemaMigrationSQL")
	if err != nil {
		return nil, err
	}
	if err := ValidateDorisSchemaEvolution(before, after); err != nil {
		return nil, err
	}
	matchedBeforeKeys := make(map[string]bool, len(before))
	var stmts []string
	for _, afterTbl := range after {
		key := dorisTableEvolutionIdentity(afterTbl)
		if beforeTbl, ok := beforeByKey[key]; ok {
			matchedBeforeKeys[key] = true
			alterStmts, err := BuildIcebergAlterTableSQL(beforeTbl, afterTbl, tenantSlug)
			if err != nil {
				return nil, err
			}
			stmts = append(stmts, alterStmts...)
			continue
		}
		if !hasIcebergTargetTable(afterTbl) {
			continue
		}
		if err := validateDorisNewTableColumns(afterTbl, "Iceberg"); err != nil {
			return nil, err
		}
		createSQL := afterTbl.BuildIcebergCreateTableSQL(tenantSlug)
		if createSQL == "" {
			return nil, fmt.Errorf("failed to build Iceberg CREATE TABLE SQL for new table %q", afterTbl.TableName)
		}
		stmts = append(stmts, createSQL)
	}
	for _, beforeTbl := range before {
		key := dorisTableEvolutionIdentity(beforeTbl)
		if !matchedBeforeKeys[key] && hasIcebergTargetTable(beforeTbl) {
			return nil, fmt.Errorf("dropping existing Iceberg table %q is forbidden in BuildIcebergSchemaMigrationSQL", beforeTbl.TableName)
		}
	}
	return stmts, nil
}

func hasDorisTargetTable(t DorisTableDescriptor) bool {
	if t.SyncTier == "ICEBERG_ONLY" {
		return false
	}
	uks := effectiveDorisUniqueKeys(t)
	dks := dedupDorisColumnList(t.DuplicateKeyColumns)
	if t.DatabaseScope == "GLOBAL_TERMINOLOGY" && t.SyncTier == "RELEASE_PARTITIONED" && len(uks) == 0 && len(dks) == 0 {
		return false
	}
	return true
}

func hasIcebergTargetTable(t DorisTableDescriptor) bool {
	return t.SyncTier != "INTERNAL_ONLY"
}

func effectiveDorisPartitionCols(t DorisTableDescriptor) []string {
	if len(t.PartitionByColumns) > 0 {
		return dedupDorisColumnList(t.PartitionByColumns)
	}
	var cols []string
	for _, c := range t.Columns {
		if c.IsPartitionKey {
			cols = append(cols, c.ColumnName)
		}
	}
	cols = dedupDorisColumnList(cols)
	if len(cols) == 0 && t.SyncTier == "MONTHLY_PARTITIONED" {
		for _, c := range t.Columns {
			if c.ColumnName == "event_month" {
				return []string{"event_month"}
			}
		}
	}
	if len(cols) == 0 && t.SyncTier == "RELEASE_PARTITIONED" {
		for _, c := range t.Columns {
			if c.ColumnName == "release_id" {
				return []string{"release_id"}
			}
		}
	}
	return cols
}

func resolveDorisAlterColumnType(c DorisColumnDescriptor) string {
	dt := strings.ToUpper(strings.TrimSpace(c.DorisType))
	if dt != "" {
		return dt
	}
	return dorisColumnIcebergDDLType(c.DorisType, c.IcebergType)
}

func dorisQualifiedTableName(t DorisTableDescriptor, slug string) string {
	switch t.DatabaseScope {
	case "GLOBAL_TERMINOLOGY":
		return "internal.terminology." + t.TableName
	case "GLOBAL_TERMINOLOGY_RAG":
		return "internal.terminology_rag." + t.TableName
	case "GLOBAL_TELEMETRY":
		return "internal.telemetry." + t.TableName
	default:
		return "internal.tenant_" + slug + "." + t.TableName
	}
}

func icebergQualifiedTableName(t DorisTableDescriptor, slug string) string {
	catalog := strings.TrimSpace(t.IcebergCatalog)
	if catalog == "" {
		catalog = "iceberg"
	}
	switch t.DatabaseScope {
	case "GLOBAL_TERMINOLOGY":
		return catalog + ".terminology." + t.TableName
	case "GLOBAL_TELEMETRY":
		return catalog + ".telemetry." + t.TableName
	case "GLOBAL_TERMINOLOGY_RAG":
		return catalog + ".terminology_rag." + t.TableName
	default:
		return catalog + ".tenant_" + slug + "." + t.TableName
	}
}

func formatDorisAlterColumnClause(c DorisColumnDescriptor, colType string, includeDefaults bool) string {
	colIdent := formatDorisDDLColumnIdent(c.ColumnName)
	clause := fmt.Sprintf("%s %s", colIdent, colType)
	if !c.Nullable {
		clause += " NOT NULL"
		if includeDefaults {
			cWithType := c
			cWithType.DorisType = colType
			if defVal, hasDef := resolveDorisColumnDefaultValue(cWithType); hasDef {
				clause += fmt.Sprintf(" DEFAULT %q", defVal)
			}
		}
	} else if includeDefaults && c.DefaultValue != "" {
		clause += fmt.Sprintf(" DEFAULT %q", c.DefaultValue)
	}
	return clause
}

func isDorisNonScalarColumnType(dorisType string) bool {
	dt := strings.ToUpper(strings.TrimSpace(dorisType))
	switch dt {
	case "JSON", "JSONB", "VARIANT":
		return true
	}
	return strings.HasPrefix(dt, "ARRAY<") || strings.HasPrefix(dt, "MAP<") || strings.HasPrefix(dt, "STRUCT<")
}

func effectiveDorisUniqueKeys(t DorisTableDescriptor) []string {
	if len(t.UniqueKeyColumns) > 0 {
		return dedupDorisColumnList(t.UniqueKeyColumns)
	}
	var uks []string
	for _, c := range t.Columns {
		if c.IsUniqueKey {
			uks = append(uks, c.ColumnName)
		}
	}
	return dedupDorisColumnList(uks)
}

func effectiveDorisDuplicateKeys(t DorisTableDescriptor) []string {
	if len(t.DuplicateKeyColumns) > 0 {
		return dedupDorisColumnList(t.DuplicateKeyColumns)
	}
	if len(effectiveDorisUniqueKeys(t)) == 0 && len(t.Columns) > 0 && t.Columns[0].ColumnName != "" {
		return []string{t.Columns[0].ColumnName}
	}
	return nil
}

func effectiveDorisDistributionCols(t DorisTableDescriptor) []string {
	if len(t.DistributionColumns) > 0 {
		return dedupDorisColumnList(t.DistributionColumns)
	}
	if s := strings.TrimSpace(t.DistributedByColumn); s != "" {
		return []string{s}
	}
	if uks := effectiveDorisUniqueKeys(t); len(uks) > 0 {
		if len(uks) > 1 && uks[0] == "tenant_id" {
			return []string{uks[1]}
		}
		return []string{uks[0]}
	}
	if dks := effectiveDorisDuplicateKeys(t); len(dks) > 0 {
		return []string{dks[0]}
	}
	return nil
}

func effectiveDorisSequenceCol(t DorisTableDescriptor) string {
	if s := strings.TrimSpace(t.SequenceCol); s != "" {
		return s
	}
	if s := strings.TrimSpace(t.SequenceColumn); s != "" {
		return s
	}
	for _, c := range t.Columns {
		if c.IsSequenceCol {
			return c.ColumnName
		}
	}
	return ""
}

func dorisStringSlicesEqual(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// IsSafeDorisTypeEvolution reports whether evolving a column from beforeType to
// afterType is either a no-op or a safe widening type change supported by
// Apache Doris 4.x Light Schema Change (LSC), StarRocks 4.x, and Apache Iceberg v2.
func IsSafeDorisTypeEvolution(beforeType, afterType string) bool {
	bt := strings.ToUpper(strings.TrimSpace(beforeType))
	at := strings.ToUpper(strings.TrimSpace(afterType))
	if bt == at {
		return true
	}
	if bt == "" || at == "" {
		return false
	}
	if strings.HasPrefix(bt, "ARRAY<") && strings.HasSuffix(bt, ">") {
		if strings.HasPrefix(at, "ARRAY<") && strings.HasSuffix(at, ">") {
			innerB := strings.TrimSuffix(strings.TrimPrefix(bt, "ARRAY<"), ">")
			innerA := strings.TrimSuffix(strings.TrimPrefix(at, "ARRAY<"), ">")
			return IsSafeDorisTypeEvolution(innerB, innerA)
		}
		return false
	}
	if p1, okB := parseDorisDatetimePrecision(bt); okB {
		if p2, okA := parseDorisDatetimePrecision(at); okA {
			return p2 >= p1
		}
		return false
	}
	canonBefore := dorisColumnStarRocksDDLType(bt, "")
	canonAfter := dorisColumnStarRocksDDLType(at, "")
	if canonBefore == canonAfter {
		return true
	}
	if m, okB := parseDorisVarcharLength(canonBefore); okB {
		if n, okA := parseDorisVarcharLength(canonAfter); okA {
			return n >= m
		}
		return canonAfter == "STRING"
	}
	if p1, s1, okB := parseDorisDecimalParams(canonBefore); okB {
		if p2, s2, okA := parseDorisDecimalParams(canonAfter); okA {
			return p2 >= p1 && s1 == s2
		}
		return false
	}
	switch canonBefore {
	case "TINYINT":
		return canonAfter == "SMALLINT" || canonAfter == "INT" || canonAfter == "BIGINT" || canonAfter == "LARGEINT"
	case "SMALLINT":
		return canonAfter == "INT" || canonAfter == "BIGINT" || canonAfter == "LARGEINT"
	case "INT":
		return canonAfter == "BIGINT" || canonAfter == "LARGEINT"
	case "BIGINT":
		return canonAfter == "LARGEINT"
	case "FLOAT":
		return canonAfter == "DOUBLE"
	case "DATE":
		_, okA := parseDorisDatetimePrecision(at)
		return okA
	default:
		return false
	}
}

func parseDorisDatetimePrecision(upperType string) (int, bool) {
	switch upperType {
	case "DATETIME", "DATETIMEV2":
		return 0, true
	}
	var inner string
	switch {
	case strings.HasPrefix(upperType, "DATETIME(") && strings.HasSuffix(upperType, ")"):
		inner = strings.TrimSuffix(strings.TrimPrefix(upperType, "DATETIME("), ")")
	case strings.HasPrefix(upperType, "DATETIMEV2(") && strings.HasSuffix(upperType, ")"):
		inner = strings.TrimSuffix(strings.TrimPrefix(upperType, "DATETIMEV2("), ")")
	default:
		return 0, false
	}
	p, err := strconv.Atoi(strings.TrimSpace(inner))
	if err != nil || p < 0 || p > 6 {
		return 0, false
	}
	return p, true
}

func parseDorisDecimalParams(upperType string) (int, int, bool) {
	var inner string
	switch {
	case strings.HasPrefix(upperType, "DECIMAL(") && strings.HasSuffix(upperType, ")"):
		inner = strings.TrimSuffix(strings.TrimPrefix(upperType, "DECIMAL("), ")")
	case strings.HasPrefix(upperType, "DECIMALV3(") && strings.HasSuffix(upperType, ")"):
		inner = strings.TrimSuffix(strings.TrimPrefix(upperType, "DECIMALV3("), ")")
	default:
		return 0, 0, false
	}
	parts := strings.Split(inner, ",")
	if len(parts) != 2 {
		return 0, 0, false
	}
	p, errP := strconv.Atoi(strings.TrimSpace(parts[0]))
	s, errS := strconv.Atoi(strings.TrimSpace(parts[1]))
	if errP != nil || errS != nil || p <= 0 || s < 0 || s > p {
		return 0, 0, false
	}
	return p, s, true
}

func parseDorisVarcharLength(upperType string) (int, bool) {
	if !strings.HasPrefix(upperType, "VARCHAR(") || !strings.HasSuffix(upperType, ")") {
		return 0, false
	}
	inner := strings.TrimSpace(strings.TrimSuffix(strings.TrimPrefix(upperType, "VARCHAR("), ")"))
	if inner == "" {
		return 0, false
	}
	n, err := strconv.Atoi(inner)
	if err != nil || n <= 0 {
		return 0, false
	}
	return n, true
}

type dorisValueScanner struct {
	values []any
}

// NewDorisValueScanner wraps a slice of column values (such as r.Values())
// into a DorisScanner for in-memory row scanning and round-trip testing.
func NewDorisValueScanner(values []any) DorisScanner {
	return &dorisValueScanner{values: values}
}

func (s *dorisValueScanner) Scan(dest ...any) error {
	if len(dest) != len(s.values) {
		return fmt.Errorf("dorisValueScanner: expected %d destination arguments, got %d", len(s.values), len(dest))
	}
	for i, d := range dest {
		rawVal := s.values[i]
		if valuer, ok := rawVal.(driver.Valuer); ok && rawVal != nil {
			var err error
			rawVal, err = valuer.Value()
			if err != nil {
				return err
			}
		}
		dv, err := driver.DefaultParameterConverter.ConvertValue(rawVal)
		if err != nil {
			return err
		}
		if sc, ok := d.(sql.Scanner); ok {
			if err := sc.Scan(dv); err != nil {
				return err
			}
			continue
		}
		switch ptr := d.(type) {
		case *any:
			*ptr = dv
		case *[]byte:
			if dv == nil {
				*ptr = nil
			} else if b, ok := dv.([]byte); ok {
				if b == nil {
					*ptr = nil
				} else {
					cp := make([]byte, len(b))
					copy(cp, b)
					*ptr = cp
				}
			} else if str, ok := dv.(string); ok {
				*ptr = []byte(str)
			} else {
				return fmt.Errorf("dorisValueScanner: cannot scan %T into *[]byte", dv)
			}
		default:
			return fmt.Errorf("dorisValueScanner: unsupported scan target %T at column %d", d, i)
		}
	}
	return nil
}

func dorisRequiredPtrValue[T any](v *T) T {
	if v == nil {
		var zero T
		return zero
	}
	return *v
}

func dorisRequiredBytesValue(b []byte) any {
	if b == nil {
		return []byte{}
	}
	return b
}

func dorisUint64Value(v uint64) any {
	if v > uint64(math.MaxInt64) {
		return strconv.FormatUint(v, 10)
	}
	return int64(v)
}

func dorisPtrUint64Value(v *uint64) any {
	if v == nil {
		return nil
	}
	return dorisUint64Value(*v)
}

func dorisRequiredPtrUint64Value(v *uint64) any {
	if v == nil {
		return int64(0)
	}
	return dorisUint64Value(*v)
}

func scanDorisUint64(raw any) (uint64, bool, error) {
	if raw == nil {
		return 0, false, nil
	}
	switch v := raw.(type) {
	case uint64:
		return v, true, nil
	case int64:
		if v < 0 {
			return 0, false, fmt.Errorf("scanDorisUint64: negative int64 %d cannot be converted to uint64", v)
		}
		return uint64(v), true, nil
	case sql.NullInt64:
		if !v.Valid {
			return 0, false, nil
		}
		if v.Int64 < 0 {
			return 0, false, fmt.Errorf("scanDorisUint64: negative int64 %d cannot be converted to uint64", v.Int64)
		}
		return uint64(v.Int64), true, nil
	case []byte:
		s := strings.TrimSpace(string(v))
		if s == "" {
			return 0, false, nil
		}
		u, err := strconv.ParseUint(s, 10, 64)
		return u, err == nil, err
	case string:
		s := strings.TrimSpace(v)
		if s == "" {
			return 0, false, nil
		}
		u, err := strconv.ParseUint(s, 10, 64)
		return u, err == nil, err
	default:
		return 0, false, fmt.Errorf("scanDorisUint64: unsupported type %T", raw)
	}
}

func scanDorisInt32(v sql.NullInt64) (int32, bool, error) {
	if !v.Valid {
		return 0, false, nil
	}
	if v.Int64 < math.MinInt32 || v.Int64 > math.MaxInt32 {
		return 0, false, fmt.Errorf("scanDorisInt32: value %d overflows int32", v.Int64)
	}
	return int32(v.Int64), true, nil
}

func scanDorisUint32(v sql.NullInt64) (uint32, bool, error) {
	if !v.Valid {
		return 0, false, nil
	}
	if v.Int64 < 0 || v.Int64 > math.MaxUint32 {
		return 0, false, fmt.Errorf("scanDorisUint32: value %d overflows uint32", v.Int64)
	}
	return uint32(v.Int64), true, nil
}

func dorisNullableDateValue(s string) any {
	if s == "" {
		return sql.NullString{}
	}
	return s
}

func dorisRequiredDateValue(s string) any {
	if s == "" {
		return "0001-01-01"
	}
	return s
}

func dorisNullableTimeValue(t time.Time) any {
	if t.IsZero() {
		return sql.NullTime{}
	}
	return t.UTC()
}

func dorisPtrTimeValue(t *time.Time) any {
	if t == nil || t.IsZero() {
		return sql.NullTime{}
	}
	return t.UTC()
}

func dorisRequiredPtrTimeValue(t *time.Time) any {
	if t == nil || t.IsZero() {
		return time.Time{}.UTC()
	}
	return t.UTC()
}

func scanDorisTime(raw any) (time.Time, bool, error) {
	if raw == nil {
		return time.Time{}, false, nil
	}
	switch v := raw.(type) {
	case time.Time:
		if v.IsZero() {
			return time.Time{}, false, nil
		}
		return v.UTC(), true, nil
	case *time.Time:
		if v == nil || v.IsZero() {
			return time.Time{}, false, nil
		}
		return v.UTC(), true, nil
	case sql.NullTime:
		if !v.Valid || v.Time.IsZero() {
			return time.Time{}, false, nil
		}
		return v.Time.UTC(), true, nil
	case sql.NullString:
		if !v.Valid {
			return time.Time{}, false, nil
		}
		return scanDorisTimeStrChecked(v.String)
	case []byte:
		return scanDorisTimeStrChecked(string(v))
	case string:
		return scanDorisTimeStrChecked(v)
	default:
		return time.Time{}, false, fmt.Errorf("scanDorisTime: unsupported type %T", raw)
	}
}

func scanDorisTimeStrChecked(s string) (time.Time, bool, error) {
	s = strings.TrimSpace(s)
	if s == "" || strings.HasPrefix(s, "0000-00-00") || strings.HasPrefix(s, "0001-01-01") {
		return time.Time{}, false, nil
	}
	t, ok := parseDorisTimeString(s)
	if !ok {
		return time.Time{}, false, fmt.Errorf("scanDorisTime: invalid datetime %q", s)
	}
	return t, true, nil
}

func parseDorisTimeString(s string) (time.Time, bool) {
	s = strings.TrimSpace(s)
	if s == "" || strings.HasPrefix(s, "0000-00-00") {
		return time.Time{}, false
	}
	layouts := []string{
		"2006-01-02 15:04:05.999999999",
		"2006-01-02 15:04:05",
		time.RFC3339Nano,
		time.RFC3339,
		"2006-01-02",
	}
	for _, layout := range layouts {
		if t, err := time.ParseInLocation(layout, s, time.UTC); err == nil {
			if t.IsZero() {
				return time.Time{}, false
			}
			return t.UTC(), true
		}
	}
	return time.Time{}, false
}

func scanDorisDateString(raw any) (string, error) {
	if raw == nil {
		return "", nil
	}
	switch v := raw.(type) {
	case time.Time:
		if v.IsZero() {
			return "", nil
		}
		return v.UTC().Format("2006-01-02"), nil
	case *time.Time:
		if v == nil || v.IsZero() {
			return "", nil
		}
		return v.UTC().Format("2006-01-02"), nil
	case sql.NullTime:
		if !v.Valid || v.Time.IsZero() {
			return "", nil
		}
		return v.Time.UTC().Format("2006-01-02"), nil
	case sql.NullString:
		if !v.Valid {
			return "", nil
		}
		return scanDorisDateStrChecked(v.String)
	case []byte:
		return scanDorisDateStrChecked(string(v))
	case string:
		return scanDorisDateStrChecked(v)
	default:
		return "", fmt.Errorf("scanDorisDateString: unsupported type %T", raw)
	}
}

func scanDorisDateStrChecked(s string) (string, error) {
	norm := normalizeDorisDateStr(s)
	if norm == "" {
		return "", nil
	}
	if _, _, _, ok := parseDorisDateParts(norm); !ok {
		return "", fmt.Errorf("scanDorisDateString: invalid date %q", s)
	}
	return norm, nil
}

func normalizeDorisDateStr(s string) string {
	s = strings.TrimSpace(s)
	if s == "" || strings.HasPrefix(s, "0000-00-00") || strings.HasPrefix(s, "0001-01-01") {
		return ""
	}
	if len(s) >= 10 && s[4] == '-' && s[7] == '-' {
		return s[:10]
	}
	return s
}

func parseDorisDateParts(s string) (int32, int32, int32, bool) {
	s = normalizeDorisDateStr(s)
	if len(s) != 10 {
		return 0, 0, 0, false
	}
	t, err := time.Parse("2006-01-02", s)
	if err != nil || t.Year() < 1 || t.Year() > 9999 {
		return 0, 0, 0, false
	}
	// #nosec G115 -- year [1,9999], month [1,12], day [1,31]
	return int32(t.Year()), int32(t.Month()), int32(t.Day()), true
}

func formatDorisDateParts(year, month, day int32) string {
	if year < 1 || year > 9999 || month < 1 || month > 12 || day < 1 || day > 31 {
		return ""
	}
	t := time.Date(int(year), time.Month(month), int(day), 0, 0, 0, 0, time.UTC)
	if t.Year() != int(year) || t.Month() != time.Month(month) || t.Day() != int(day) {
		return ""
	}
	return fmt.Sprintf("%04d-%02d-%02d", year, month, day)
}

func stripProtoEnumPrefix(val, prefix string) string {
	if val == "" || val == prefix+"UNSPECIFIED" || val == "UNSPECIFIED" {
		return ""
	}
	return strings.TrimPrefix(val, prefix)
}

func lookupProtoEnumValueOk(valMap map[string]int32, raw, prefix string) (int32, bool) {
	if raw == "" {
		return 0, false
	}
	if v, ok := valMap[raw]; ok {
		return v, true
	}
	if prefix != "" {
		if v, ok := valMap[prefix+raw]; ok {
			return v, true
		}
	}
	return 0, false
}

func lookupProtoEnumValue(valMap map[string]int32, raw, prefix string) int32 {
	v, _ := lookupProtoEnumValueOk(valMap, raw, prefix)
	return v
}

func parseDorisDateToProto(s string) *date.Date {
	year, month, day, ok := parseDorisDateParts(s)
	if !ok {
		return nil
	}
	return &date.Date{
		Year:  year,
		Month: month,
		Day:   day,
	}
}

func formatProtoDateToDoris(d *date.Date) string {
	if d == nil {
		return ""
	}
	return formatDorisDateParts(d.GetYear(), d.GetMonth(), d.GetDay())
}

